def _compile_glob(pattern: str) -> re.Pattern[str]:
    """Compile a policy glob into an anchored regex.

    Uses :func:`fnmatch.translate` so ``*`` crosses ``/`` boundaries;
    a ``**/`` prefix is folded away first so it can also match zero
    directory segments (e.g. ``**/*.log`` matches ``run.log``).
    """
    normalized = pattern.replace("**/", "")
    return re.compile(fnmatch.translate(normalized))
